import{_ as o,o as t,c as n,ag as e}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学快报 | 2026年7月23日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-07-23.md","filePath":"science-log/src/reconstructed/2026-07-23.md"}'),a={name:"science-log/src/reconstructed/2026-07-23.md"};function s(g,r,i,l,c,h){return t(),n("div",null,[...r[0]||(r[0]=[e('<h1 id="🔬-科学快报-2026年7月23日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年7月23日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年7月23日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年7月23日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-07 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 检索说明：2026-07-23 为<strong>周四</strong>。CrossRef 按 <code>from-pub-date=until-pub-date=2026-07-23</code> 检索：Nature（0028-0836）命中 9 条但<strong>研究论文 0 条</strong>（全部为 <code>10.1038/d41586-…</code> 新闻/Briefing，按要求丢弃）；Science 前缀（10.1126）命中 46 条（含研究论文与新闻混排）；PNAS（0027-8424）命中 10 条。故科学 5 篇取自<strong>当日真实出版</strong>的 Science 3 篇 + PNAS 2 篇。AI 5 篇严格取自 arXiv <code>submittedDate:[202607230000 TO 202607232359]</code> 的 cs.AI 真实条目（命中 40 篇）。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202607230000 TO 202607232359]</code>（cs.AI，40 条）+ CrossRef 摘要核验 ｜ 重建日：2026-11-07</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧱-台阶几何「引导」层间滑移-纯相菱方石墨烯长到-160×80-微米" tabindex="-1">🧱 台阶几何「引导」层间滑移：纯相菱方石墨烯长到 160×80 微米 <a class="header-anchor" href="#🧱-台阶几何「引导」层间滑移-纯相菱方石墨烯长到-160×80-微米" aria-label="Permalink to &quot;🧱 台阶几何「引导」层间滑移：纯相菱方石墨烯长到 160×80 微米&quot;">​</a></h3><p><strong>Step geometry–guided growth of rhombohedral graphene</strong><em>Science（2026）</em></p><p>菱方（ABC）堆叠石墨烯是研究关联与拓扑物理的明星平台，但它热力学上亚稳、动力学上不稳，规模化制备纯相一直是死结。北京大学/中科院物理所刘开辉、陆晓博、刘中恺等人（Mengze Zhao、Zhibin Zhang、Xin Sui、Feng Ding、Enge Wang 等 19 人）改用<strong>台阶几何引导的外延策略</strong>，让衬底台阶的取向与高度决定层间滑移方向，从而<strong>确定性地</strong>控制堆叠序列，得到相纯度 <strong>&gt;99%</strong> 的菱方石墨烯，单晶区面积达 <strong>160 μm × 80 μm</strong>、厚度从约 15 层覆盖到约 120 nm。样品建立起了首个从少层膜到约 200 层体材料的<strong>拉曼指纹与内禀能带</strong>完整参考数据集。输运测量直接看到<strong>层间反铁磁态</strong>与<strong>量子反常霍尔效应</strong>——这说明曾被视作「实验室里几微米见方」的关联拓扑物理，具备了按需放大、可复现的材料底座。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aed9202" target="_blank" rel="noreferrer">10.1126/science.aed9202</a></p><h3 id="🪐-18-年光谱里找出行星周期-gj-436-b-的磁场被夹到-6–110-高斯" tabindex="-1">🪐 18 年光谱里找出行星周期：GJ 436 b 的磁场被夹到 6–110 高斯 <a class="header-anchor" href="#🪐-18-年光谱里找出行星周期-gj-436-b-的磁场被夹到-6–110-高斯" aria-label="Permalink to &quot;🪐 18 年光谱里找出行星周期：GJ 436 b 的磁场被夹到 6–110 高斯&quot;">​</a></h3><p><strong>Constraining an exoplanet&#39;s magnetic field using star-planet interactions</strong><em>Science（2026）</em></p><p>理论早有预言：一颗磁场足够强的行星若近距离绕转，会与宿主星产生<strong>星—行星磁相互作用</strong>，表现为与行星轨道周期同步的光学或射电活动信号；但这条预言此前从未被&quot;读数&quot;成功。D. Revilla、P. J. Amado、R. Luque、A. F. Lanza、A. Reiners、I. Ribas 等（CARMENES 联盟，西班牙 IAA-CSIC 等）分析了 <strong>GJ 436 的 18 年高分辨率光学光谱</strong>——那是一颗被海王星大小行星以<strong>极轨偏心轨道</strong>绕转的低质量恒星。恒星活动指标在<strong>行星轨道周期</strong>上出现增强，并被自转与恒星 <strong>8 年磁活动周</strong>共同调制。用几何模型反演，只有 GJ 436 b 的磁场强度在 <strong>6–110 高斯</strong>之间才能同时复现这几个周期。这是首次用光谱信号给一颗系外行星的磁场定出数值区间，为&quot;行星磁场—大气逃逸—宜居性&quot;这条链条补上了此前完全缺失的一环。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.adv3075" target="_blank" rel="noreferrer">10.1126/science.adv3075</a></p><h3 id="🧠-海马体衰老的四维重编程-小胶质细胞「换血」、星形胶质细胞退场、3d-基因组全面侵蚀" tabindex="-1">🧠 海马体衰老的四维重编程：小胶质细胞「换血」、星形胶质细胞退场、3D 基因组全面侵蚀 <a class="header-anchor" href="#🧠-海马体衰老的四维重编程-小胶质细胞「换血」、星形胶质细胞退场、3d-基因组全面侵蚀" aria-label="Permalink to &quot;🧠 海马体衰老的四维重编程：小胶质细胞「换血」、星形胶质细胞退场、3D 基因组全面侵蚀&quot;">​</a></h3><p><strong>Epigenetic and 3D genome reprogramming during the aging of the human hippocampus</strong><em>Science（2026）</em></p><p>基因表达在人脑衰老中会变，但调控层到底改了什么长期不清楚。Nathan R. Zemke、Seoyeon Lee、Sainath Mamde、Nicole Berchtold、Ting Wang 等对<strong>跨越成年全生命周期的人海马组织</strong>做了单核多组学联测：基因表达、染色质可及性、DNA 甲基化，外加<strong>三维染色质构象</strong>。结果是三类截然不同的变化：调控程序里既有线性漂移也有<strong>非线性跳变</strong>；<strong>50 至 75 岁之间，胚胎卵黄囊来源的小胶质细胞被耗竭，由类似外周血单核细胞来源的小胶质细胞替换</strong>；海马星形胶质细胞（包括调控突触传递的那群）随年龄显著减少；而跨越所有细胞类型，<strong>3D 基因组架构发生全局性&quot;侵蚀&quot;</strong>。这把人脑衰老从&quot;某些基因上调下调&quot;升级为&quot;细胞组成替换 + 空间基因组解体&quot;的双重过程，为细胞类型特异的衰老干预给出了明确的靶点清单。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.adt8307" target="_blank" rel="noreferrer">10.1126/science.adt8307</a></p><h3 id="🦴-绳文与弥生两副高覆盖基因组-冰期后人口轨迹彻底分岔-amy1-拷贝数在稻作之前就已增高" tabindex="-1">🦴 绳文与弥生两副高覆盖基因组：冰期后人口轨迹彻底分岔，AMY1 拷贝数在稻作之前就已增高 <a class="header-anchor" href="#🦴-绳文与弥生两副高覆盖基因组-冰期后人口轨迹彻底分岔-amy1-拷贝数在稻作之前就已增高" aria-label="Permalink to &quot;🦴 绳文与弥生两副高覆盖基因组：冰期后人口轨迹彻底分岔，AMY1 拷贝数在稻作之前就已增高&quot;">​</a></h3><p><strong>High-coverage ancient genomes reveal divergent population histories and prehistoric starch-related genetic variation in the Japanese archipelago</strong><em>PNAS（2026）</em></p><p>日本本土古 DNA 保存差，此前几乎没有高分辨率基因组。Koji Ishiya、Fuzuki Mizuno、Jun Gojobori、Li Wang、Shintaroh Ueda 等报告了两副低污染、高覆盖的本土古基因组：一例<strong>绳文早期个体（&gt;67×）</strong>、一例<strong>弥生中期个体（&gt;46×）</strong>，达到二倍体基因分型与个体级人口推断所需的精度。人口重建显示两条谱系在<strong>末次盛冰期（LGM）都经历收缩</strong>，但此后彻底分岔——绳文谱系是冰期后的长期稳定、几乎无可辨识的扩张，弥生相关祖先群体则持续缓慢增长；弥生中期与今日本土日本人在遗传上<strong>明显连续</strong>，且弥生个体本身已带有大陆互动的复杂祖源背景。最反直觉的一点是：绳文早期个体携带<strong>更高的唾液淀粉酶 AMY1 拷贝数</strong>，说明与富淀粉饮食相关的拷贝数变异，在稻作大规模扩散<strong>之前</strong>就已存在于列岛。这把&quot;农业→基因适应&quot;的因果方向翻了个面：适应可能先到，农业后到。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2606162123" target="_blank" rel="noreferrer">10.1073/pnas.2606162123</a></p><h3 id="🧪-活性—抗性权衡-复活七百万年前的酶-看到抗药性每次都以催化效率为代价" tabindex="-1">🧪 活性—抗性权衡：复活七百万年前的酶，看到抗药性每次都以催化效率为代价 <a class="header-anchor" href="#🧪-活性—抗性权衡-复活七百万年前的酶-看到抗药性每次都以催化效率为代价" aria-label="Permalink to &quot;🧪 活性—抗性权衡：复活七百万年前的酶，看到抗药性每次都以催化效率为代价&quot;">​</a></h3><p><strong>An activity–resistance trade-off constrains enzyme evolution</strong><em>PNAS（2026）</em></p><p>抗生素产生菌身上的&quot;自抗性基因&quot;是个悖论：抗性怎么可能在抗生素出现之前就进化出来？Alexander W. Sarkis、Jens Laurids Sørensen、Douglas L. Theobald、Lizbeth Hedstrom 等以<strong>霉酚酸（MPA）<strong>为模型——它抑制次黄嘌呤单核苷酸脱氢酶（IMPDH）——顺着 MPA 生物合成基因簇里的</strong>抗性版 IMPDH-B</strong> 追演化史。IMPDH-B 的同源物不只在产 MPA 的真菌里，也在大量<strong>不产 MPA 的真菌</strong>中，且这些基因组里还残留着 MPA 基因簇的碎片；其系统树与物种树不一致，指向 Aspergillus 与 Sordariomycetes 之间的<strong>多次水平基因转移</strong>。团队表征了 11 个现存酶（5 个来自产生菌、6 个来自非产生菌）与 <strong>7 个复活祖先酶（Anc1–Anc7）</strong>：MPA 抗性出现在 <strong>Anc2 与 Anc3 之间</strong>，并<strong>恰好伴随催化效率的下降</strong>；在祖先与现存酶中，&quot;抗性强&quot;与&quot;活性低&quot;始终强相关，这条权衡已持续数百万年。更有意思的是，这些酶同时对<strong>利巴韦林单磷酸（RVP）<strong>抗性，而 MPA 与 RVP 结合的是相近构象——所以这条权衡可能是&quot;同时抗多种抑制剂&quot;这一设计约束的产物；Anc1 与 Anc2 对 MPA 同样敏感，但 Anc2 已降低对 RVP 的敏感性，暗示</strong>先有的另一种抗性为后来 MPA 生物合成的出现铺好了许可性背景</strong>。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2602068123" target="_blank" rel="noreferrer">10.1073/pnas.2602068123</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🎓-leact-从专家的「沉默动作」里反推思维链" tabindex="-1">🎓 LeAct：从专家的「沉默动作」里反推思维链 <a class="header-anchor" href="#🎓-leact-从专家的「沉默动作」里反推思维链" aria-label="Permalink to &quot;🎓 LeAct：从专家的「沉默动作」里反推思维链&quot;">​</a></h3><p><strong>LeAct: Learning to Reason from Expert Actions</strong><em>arXiv（2026）</em></p><p>推理模型吃的是推理数据，来源无非人工标注或从更强模型蒸馏；但真正的推理富矿其实是<strong>专家系统</strong>——游戏引擎、经典规划器、定理证明器，它们在大范围任务上都能给出近最优动作，唯独<strong>不说话</strong>：直接给出动作，不写下背后的思维链。Ziran Yang、Chengshuai Shi、Raj Ghugare、Benjamin Eysenbach、Karthik Narasimhan、Chi Jin（普林斯顿等）把这条缺失的 CoT 当作<strong>潜变量</strong>：学生自己为每个专家动作采样候选 CoT，只保留那些<strong>实测能提高自己复现该动作概率</strong>的候选——用动作的可验证性替代对推理文本的监督。在不完全信息博弈与一个模拟机器人基准上，LeAct 在小规模可枚举博弈上触到求解器的数值下限；规模放大后与求解器的距离比最强的 expert-iteration 基线<strong>近 5 倍</strong>；在约 10⁹ 信息集的 Flop Hold&#39;em 上对阵胜出 <strong>+60 mbb/g</strong>；机器人探针里它是<strong>唯一一个</strong>优于直接模仿的训练配方。结论相当直接：专家系统可以成为基础模型一类全新的推理教师。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.21856" target="_blank" rel="noreferrer">2607.21856</a></p><h3 id="📏-qlpo-不改奖励函数-靠重采样把思维链压短-30–70" tabindex="-1">📏 QLPO：不改奖励函数，靠重采样把思维链压短 30–70% <a class="header-anchor" href="#📏-qlpo-不改奖励函数-靠重采样把思维链压短-30–70" aria-label="Permalink to &quot;📏 QLPO：不改奖励函数，靠重采样把思维链压短 30–70%&quot;">​</a></h3><p><strong>QLPO: Quadrant-weighted Sampling for Length-aware Policy Optimization</strong><em>arXiv（2026）</em></p><p>大推理模型在 RL 中会自发长出很长的思维链，延迟与部署成本随之飙升；现有长度控制手段要么加显式长度惩罚、要么挂额外控制模块，调参麻烦还可能伤推理质量。Siwei Chen、Siqi Chen、Xupeng Miao、Bin Cui（北京大学）提出 <strong>QLPO</strong>：一个纯重采样式的 GRPO 变体，<strong>完全不碰奖励函数</strong>。做法是先<strong>过量生成</strong>候选回答，再按「保持经验正确/错误比例不变」的约束重新采样训练组，同时<strong>偏向短的正确答案与长的错误答案</strong>——只改变训练分布，就隐式地把输出推短。在 1.5B 到 32B 的基座模型与强推理模型上，QLPO 稳定改善准确率—长度权衡，<strong>响应长度降低 30%–70% 而推理性能保持</strong>。它的意义在于把&quot;长度控制&quot;从奖励工程问题变成<strong>采样分布问题</strong>：不需要新超参、不需要改目标函数，也就没有惩罚项常见的质量塌陷。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.21793" target="_blank" rel="noreferrer">2607.21793</a></p><h3 id="📚-数据质量压过容量-把文档烤进-lora-一次清洗把闭卷准确率从-57-7-抬到-85-7" tabindex="-1">📚 数据质量压过容量：把文档烤进 LoRA，一次清洗把闭卷准确率从 57.7% 抬到 85.7% <a class="header-anchor" href="#📚-数据质量压过容量-把文档烤进-lora-一次清洗把闭卷准确率从-57-7-抬到-85-7" aria-label="Permalink to &quot;📚 数据质量压过容量：把文档烤进 LoRA，一次清洗把闭卷准确率从 57.7% 抬到 85.7%&quot;">​</a></h3><p><strong>Data Quality over Capacity: Internalizing Documents into LoRA Adapters for Closed-Book QA</strong><em>arXiv（2026）</em></p><p>如果把语料直接&quot;烤&quot;进权重，闭卷问答就不再需要检索、也不占上下文预算。Joan Figuerola Hurtado 用 4-bit Gemma-4-e4b + LoRA，从单文档一路做到 <strong>99 文档语料</strong>、约 <strong>100 次训练运行</strong>，得到一个清晰的分解：一旦适配器容量够了，<strong>训练数据质量就是主导变量</strong>，其影响超过 LoRA rank、学习率与两种替代架构之和；而容量本身是一道<strong>硬门槛</strong>，低于门槛时任何数据干预都救不回来。一次单纯的清洗（把标准答案压缩成 1–6 词的规范片段、剔掉琐碎事实）就让 15 文档语料的闭卷准确率从 <strong>57.7% 提到 85.7%</strong>，比任何架构改动都大。他还给出了一个很扎人的对照：内部化适配器召回 <strong>84.2%</strong>，胜过 BM25-RAG 配基座阅读器（58.9%）、甚至胜过现实版 gold-chunk oracle（65.6%），且延迟更低。论文把三次误判也完整写了出来，本身就是一份实证调试 LLM 训练的案例集。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.21861" target="_blank" rel="noreferrer">2607.21861</a></p><h3 id="🛡️-toolguardian-用答案集编程给-agent-tool-交互做可审计的策略层" tabindex="-1">🛡️ ToolGuardian：用答案集编程给 agent-tool 交互做可审计的策略层 <a class="header-anchor" href="#🛡️-toolguardian-用答案集编程给-agent-tool-交互做可审计的策略层" aria-label="Permalink to &quot;🛡️ ToolGuardian：用答案集编程给 agent-tool 交互做可审计的策略层&quot;">​</a></h3><p><strong>ToolGuardian: Declarative Security for AI Agent-Tool Interactions</strong><em>arXiv（2026）</em></p><p>Agent 依赖外部工具，能力扩张的同时长出一条新攻击面：第三方工具在接口上人畜无害，<strong>实现里</strong>却埋着不安全行为。现有防御要么依赖弱元数据，要么把&quot;刻画&quot;与&quot;策略判断&quot;压成一个决定，要么用启发式/LLM 执法——无法对任务上下文与多工具组合做确定性、可审计的推理。Arun Ravindran、Saurabh Deochake 的 ToolGuardian 分两步：<strong>准入前审查</strong>用渐进式刻画把证据转成结构化事实（描述=声明的意图、系统调用轨迹=粗粒度行为、mock 执行=观测到的实际效果、源码分析=潜在行为）；<strong>运行时授权</strong>则由一层基于<strong>答案集编程（ASP）<strong>的声明式策略负责，显式地对能力、效果、任务上下文与</strong>工具组合</strong>做推理。在 16 个 MCP 风格工具（其中 8 个恶意变体源自真实开源工具）与 20 个运行时场景上，ASP 用描述+syscall+观测效果证据取得 <strong>deny 类 F1 = 0.86、准确率 88%</strong>；运行时授权在完整规则下全部分类正确，而消融显示<strong>去掉组合规则与一致性规则</strong>后性能显著塌陷——说明&quot;多工具组合&quot;才是这类安全问题的真正难点。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.21835" target="_blank" rel="noreferrer">2607.21835</a></p><h3 id="🖼️-vcsd-把「擦掉图像内容」变成自蒸馏的对比信号" tabindex="-1">🖼️ VCSD：把「擦掉图像内容」变成自蒸馏的对比信号 <a class="header-anchor" href="#🖼️-vcsd-把「擦掉图像内容」变成自蒸馏的对比信号" aria-label="Permalink to &quot;🖼️ VCSD：把「擦掉图像内容」变成自蒸馏的对比信号&quot;">​</a></h3><p><strong>Visual Contrastive Self-Distillation</strong><em>arXiv（2026）</em></p><p>On-policy 自蒸馏（OPSD）省掉了外部教师，但仍需制造&quot;师生信息不对称&quot;——常见做法是给教师特权答案或额外视觉证据。Yijun Liang、Yunjie Tian、Yijiang Li、Tianyi Zhou、Di Fu 等问了一个更狠的问题：这两样能不能都去掉，让不对称<strong>只由输入条件</strong>产生？<strong>VCSD</strong> 的做法是把&quot;删除图像内容&quot;变成蒸馏信号：在每个学生已生成的回答前缀处，EMA 教师在同一 prompt、同一前缀下给出两个下一 token 分布——一个条件于<strong>原图</strong>，一个条件于<strong>内容被擦除的对照图</strong>；两者的 token 级对数概率差，恰好高亮出&quot;其似然被这张图的具体内容<strong>专门</strong>抬升&quot;的候选 token。用这个对比在教师原图分布的合理支撑内做锐化，再把完整的分布目标蒸馏给学生。在 ViRL39K 上，VCSD 在 Qwen3-VL 与 Qwen3.5 各规模上一致优于匹配的 OPSD：七基准总分 Qwen3-VL-8B <strong>72.51%→76.26%</strong>，Qwen3.5-9B <strong>74.97%→79.24%</strong>，六个评估规模全部有增益，且<strong>不需要外部教师、特权答案、视觉证据信号、推理轨迹，也不增加推理成本</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.21556" target="_blank" rel="noreferrer">2607.21556</a></p><blockquote><p>📅 日期：2026-07-23 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const d=o(a,[["render",s]]);export{p as __pageData,d as default};
